        propagationConf.writeXml(new FileWriter(PROPAGATION_CONF_XML));
        Configuration.dumpConfiguration(propagationConf, new OutputStreamWriter(System.out));
        Configuration.addDefaultResource(PROPAGATION_CONF_XML);
    }

